#include "device.h"
static void copy_name(char *d,const char *s){uint32_t i=0;if(!s){d[0]='\0';return;}while(s[i]!='\0'&&i+1u<PROS_DEVICE_NAME_MAX){d[i]=s[i];++i;}d[i]='\0';}
void device_init(struct pros_device *d,uint32_t h,const char *n,const struct pros_device_id *id,enum pros_device_class c){if(!d)return;d->handle=h;copy_name(d->name,n);if(id)d->id=*id;else{d->id.bus=PROS_DEVICE_BUS_UNKNOWN;d->id.vendor_id=d->id.device_id=d->id.subsystem_vendor_id=d->id.subsystem_device_id=0xffffu;d->id.class_code=d->id.subclass=d->id.prog_if=0xffu;}d->class=c;d->driver_data=0;d->claimed=0;}
int device_matches_id(const struct pros_device *d,const struct pros_device_id *id){if(!d||!id||d->id.bus!=id->bus)return 0;if(id->vendor_id!=0xffffu&&d->id.vendor_id!=id->vendor_id)return 0;if(id->device_id!=0xffffu&&d->id.device_id!=id->device_id)return 0;if(id->subsystem_vendor_id!=0xffffu&&d->id.subsystem_vendor_id!=id->subsystem_vendor_id)return 0;if(id->subsystem_device_id!=0xffffu&&d->id.subsystem_device_id!=id->subsystem_device_id)return 0;if(id->class_code!=0xffu&&d->id.class_code!=id->class_code)return 0;if(id->subclass!=0xffu&&d->id.subclass!=id->subclass)return 0;if(id->prog_if!=0xffu&&d->id.prog_if!=id->prog_if)return 0;return 1;}
